import{_ as o,o as a,c as t,a0 as n}from"./chunks/framework.ChlVJx0I.js";const b=JSON.parse('{"title":"bash_bg tool row shows the plain command line","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0024-bash-bg-tool-row-shows-the-plain-command-line.md","filePath":"adr/0024-bash-bg-tool-row-shows-the-plain-command-line.md","lastUpdated":1790109103000}'),s={name:"adr/0024-bash-bg-tool-row-shows-the-plain-command-line.md"};function h(r,e,l,i,d,m){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="bash-bg-tool-row-shows-the-plain-command-line" tabindex="-1">bash_bg tool row shows the plain command line <a class="header-anchor" href="#bash-bg-tool-row-shows-the-plain-command-line" aria-label="Permalink to &quot;bash_bg tool row shows the plain command line&quot;">​</a></h1><p>The bash_bg tool row (the TUI entry for the call in an agent turn) showed only the bold tool name, with the command visible nowhere in the row. The row now renders the command as <code>$ &lt;command&gt;</code>, the same line shape as the built-in bash row, with no background marker. The tool name &quot;Bash background&quot; already says the command is backgrounded, and the command line is the true intent.</p><p><strong>Considered options</strong>: a <code>$ &lt;command&gt; &amp;</code> suffix, faithful to the shell but repeating what the tool name already says; a <code>bg $ &lt;command&gt;</code> prefix, which breaks the <code>$</code> line shape the operator scans across the bash rows beside it. Both were rejected in favor of the plain line.</p>',3)])])}const p=o(s,[["render",h]]);export{b as __pageData,p as default};
